@Repository
public class RobustUserService {
    private final UserRepository userRepository;
    private final CacheManager cacheManager;
    private final RedissonClient redissonClient;

    public RobustUserService(UserRepository userRepository, CacheManager cacheManager, RedissonClient redissonClient) {
        this.userRepository = userRepository;
        this.cacheManager = cacheManager;
        this.redissonClient = redissonClient;
    }

    @Transactional
    public void updateUserEmail(Long userId, String newEmail) {
        userRepository.updateEmail(userId, newEmail);

        String cacheKey = "user:" + userId;
        Rlock lock = redissonClient.getLock("lock:" + cacheKey);

        try {
            if (lock.tryLock(3, 5, TimeUnit.SECONDS)) {
                // Evict local and distributed cache synchronously within lock boundary
                Cache cache = cacheManager.getCache("users");
                if (cache != null) {
                    cache.evict(userId);
                }
                redissonClient.getBucket(cacheKey).delete();
            } 
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new CacheInvalidationException("Interrupted during cache eviction lock acquisition", e);
        } finally {
            if (lock.isHeldByCurrentThread()) {
                lock.unlock();
            }
        }
    }
}
